code.C:
#include <stdio.h>

int main() {
    long long a, b;
    if (scanf("%lld %lld", &a, &b) == 2) {
        long long prod = 0;
        for (long long i = 0; i < b; i++) prod += a;
        printf("%lld\n", prod);
    }
    return 0;
}

